result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/cradle.js", "content": "import * as THREE from 'three';

/**
 * Idealized Newton's cradle.
 *
 * Deterministic animation contract:
 *  - Period T = 2 (time units).
 *  - First half of the cycle: only the leftmost pivot swings,
 *    angle = A * sin(PI * t') with t' the elapsed time inside that half
 *    (t' in [0, 1)), swinging from its raised side (+z rotation).
 *  - Second half: only the rightmost pivot mirrors it,
 *    angle = -A * sin(PI * t'') with t'' = t - 1 (negative z rotation).
 *  - All other pivots are exactly zero at all times (idealized momentum
 *    transfer through the middle balls).
 *  - Amplitude A = 0.6 rad.
 */

export const AMPLITUDE = 0.6;
export const PERIOD = 2;

/**
 * Build the cradle scene graph.
 *
 * @param {{balls?: number, stringLen?: number}} [opts]
 * @returns {{
 *   group: THREE.Group,        // whole toy; add to your scene
 *   frame: THREE.Group,        // base + posts + top bar
 *   pivots: THREE.Group[],     // hinged at the top bar, one per ball
 *   balls: THREE.Mesh[],
 *   ballRadius: number,
 *   stringLen: number
 * }}
 */
export function buildCradle({ balls = 5, stringLen = 4 } = {}) {
  if (!Number.isInteger(balls) || balls < 1) {
    throw new RangeError(`balls must be a positive integer, got ${balls}`);
  }
  if (!(stringLen > 0)) {
    throw new RangeError(`stringLen must be positive, got ${stringLen}`);
  }

  const group = new THREE.Group();
  group.name = 'cradle';

  // --- Frame -------------------------------------------------------------
  const frame = new THREE.Group();
  frame.name = 'frame';
  group.add(frame);

  const ballRadius = 0.5;
  const spacing = 2 * ballRadius;
  const width = spacing * (balls - 1);
  const pivotY = stringLen + ballRadius; // resting balls just touch y = 0

  const metal = new THREE.MeshStandardMaterial({
    color: 0x9aa0a8,
    metalness: 0.85,
    roughness: 0.35,
  });

  const baseGeom = new THREE.BoxGeometry(width + 3, 0.25, 1.4);
  const base = new THREE.Mesh(baseGeom, metal);
  base.name = 'base';
  base.position.y = -ballRadius - 0.125;
  frame.add(base);

  const postGeom = new THREE.CylinderGeometry(0.09, 0.09, pivotY + ballRadius, 16);
  for (const side of [-1, 1]) {
    const post = new THREE.Mesh(postGeom, metal);
    post.name = side < 0 ? 'post-left' : 'post-right';
    post.position.set((side * (width + 2)) / 2, (pivotY - ballRadius) / 2, 0);
    frame.add(post);
  }

  const barGeom = new THREE.CylinderGeometry(0.07, 0.07, width + 2, 16);
  const bar = new THREE.Mesh(barGeom, metal);
  bar.name = 'top-bar';
  bar.rotation.z = Math.PI / 2;
  bar.position.y = pivotY;
  frame.add(bar);

  // --- Pivots and balls ---------------------------------------------------
  const pivots = [];
  const ballsOut = [];

  const ballGeom = new THREE.SphereGeometry(ballRadius, 32, 32);
  const ballMat = new THREE.MeshStandardMaterial({
    color: 0xc8ccd4,
    metalness: 0.95,
    roughness: 0.15,
  });
  const stringMat = new THREE.LineBasicMaterial({ color: 0x555555 });

  for (let i = 0; i < balls; i++) {
    const x = -width / 2 + i * spacing;

    // Pivot group is the hinge point, pinned to the top bar.
    const pivot = new THREE.Group();
    pivot.name = `pivot-${i}`;
    pivot.position.set(x, pivotY, 0);
    group.add(pivot);
    pivots.push(pivot);

    // Ball hangs exactly stringLen below its pivot (rest pose).
    const ball = new THREE.Mesh(ballGeom, ballMat);
    ball.name = `ball-${i}`;
    ball.position.set(0, -stringLen, 0);
    pivot.add(ball);
    ballsOut.push(ball);

    // Cosmetic twin strings from the bar down to the ball (visual only).
    const pts = [
      new THREE.Vector3(-0.35, 0, 0),
      new THREE.Vector3(0, -stringLen, 0),
      new THREE.Vector3(0.35, 0, 0),
    ];
    const strings = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints(pts),
      stringMat,
    );
    strings.name = `strings-${i}`;
    pivot.add(strings);
  }

  return { group, frame, pivots, balls: ballsOut, ballRadius, stringLen };
}

/**
 * Pose the cradle at time t. Pure function of t (deterministic and
 * periodic with period T = 2); call updateMatrixWorld on c.group before
 * reading world-space positions.
 *
 * @param {ReturnType<typeof buildCradle>} c
 * @param {number} t time in seconds (any real number)
 */
export function animateCradle(c, t) {
  // Reset every hinge so all non-active pivots are exactly zero.
  for (const pivot of c.pivots) pivot.rotation.z = 0;

  // Wrap into [0, T).
  let tm = t % PERIOD;
  if (tm < 0) tm += PERIOD;

  if (tm < PERIOD / 2) {
    // Leftmost ball swings out on its raised side.
    c.pivots[0].rotation.z = AMPLITUDE * Math.sin(Math.PI * tm);
  } else {
    // Rightmost ball mirrors it during the second half.
    const u = tm - PERIOD / 2;
    c.pivots[c.pivots.length - 1].rotation.z =
      -AMPLITUDE * Math.sin(Math.PI * u);
  }
}
"})
