result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/cradle.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildCradle, animateCradle, AMPLITUDE, PERIOD } from '../src/cradle.js';

const EPS = 1e-9;

function makeCradle() {
  const c = buildCradle({ balls: 5, stringLen: 4 });
  c.group.updateMatrixWorld(true);
  return c;
}

describe('animateCradle', () => {
  it('at t = 0.5 the left pivot is at +A and all others are exactly 0', () => {
    const c = makeCradle();
    animateCradle(c, 0.5);
    expect(c.pivots[0].rotation.z).toBeCloseTo(AMPLITUDE, 12);
    expect(Math.abs(c.pivots[0].rotation.z - AMPLITUDE)).toBeLessThan(EPS);
    for (let i = 1; i < c.pivots.length; i++) {
      expect(c.pivots[i].rotation.z).toBe(0);
    }
  });

  it('at t = 1.5 the right pivot is at -A and the left is 0', () => {
    const c = makeCradle();
    animateCradle(c, 1.5);
    const last = c.pivots.length - 1;
    expect(c.pivots[last].rotation.z).toBeCloseTo(-AMPLITUDE, 12);
    expect(Math.abs(c.pivots[last].rotation.z + AMPLITUDE)).toBeLessThan(EPS);
    for (let i = 0; i < last; i++) {
      expect(c.pivots[i].rotation.z).toBe(0);
    }
  });

  it('is periodic with period T = 2 across sampled times', () => {
    const a = buildCradle({ balls: 5, stringLen: 4 });
    const b = buildCradle({ balls: 5, stringLen: 4 });
    for (let k = 0; k < 10; k++) {
      const t = (k / 10) * PERIOD; // sample one full period
      animateCradle(a, t);
      animateCradle(b, t + PERIOD);
      for (let i = 0; i < a.pivots.length; i++) {
        const za = a.pivots[i].rotation.z;
        const zb = b.pivots[i].rotation.z;
        expect(Math.abs(za - zb)).toBeLessThan(EPS);
      }
    }
  });

  it('balls hang stringLen below their pivots in world space', () => {
    const stringLen = 4;
    const c = buildCradle({ balls: 5, stringLen });
    // Check in both rest pose and mid-swing.
    for (const t of [0, 0.25, 0.5, 1.25, 1.5]) {
      animateCradle(c, t);
      c.group.updateMatrixWorld(true);
      for (let i = 0; i < c.balls.length; i++) {
        const pivotPos = new THREE.Vector3();
        const ballPos = new THREE.Vector3();
        c.pivots[i].getWorldPosition(pivotPos);
        c.balls[i].getWorldPosition(ballPos);
        // Rigid pendulum: distance from hinge equals stringLen...
        expect(ballPos.distanceTo(pivotPos)).toBeCloseTo(stringLen, 9);
        // ...and specifically the ball hangs straight down by stringLen
        // along the pivot's local -y axis, which for the vertical drop
        // component means world y offset magnitude <= stringLen with the
        // exact rigid-rod constraint above; at zero rotation it is exact.
        if (c.pivots[i].rotation.z === 0) {
          expect(pivotPos.y - ballPos.y).toBeCloseTo(stringLen, 9);
        }
      }
    }
  });

  it('resting balls sit at consistent heights and spacing', () => {
    const c = makeCradle();
    animateCradle(c, 0);
    c.group.updateMatrixWorld(true);
    const xs = [];
    for (let i = 0; i < c.balls.length; i++) {
      const p = new THREE.Vector3();
      c.balls[i].getWorldPosition(p);
      xs.push(p.x);
    }
    for (let i = 1; i < xs.length; i++) {
      expect(xs[i] - xs[i - 1]).toBeCloseTo(2 * c.ballRadius, 9);
    }
  });
});
"})
